//! ST's Bare Driver for the histogram parts of the 1D family, with the host post-processing — the
//! port of the reference's `vl53lx/uld/bare/` (via the Java and C# ports).
//!
//! - [`tables`] — the register-block layout and tuning parameters (generated by
//!   `scripts/gen_vl53lx_bare_tables.py` from the Python reference).
//! - [`image`] — one register block ([`RegBlock`]) and the whole device image ([`DeviceImage`]).
//! - [`nvm`] — the raw NVM regions the blocks do not cover.
//! - [`math`] — SPAD geometry and timing maths.
//! - [`core`] — the structs: [`HistConfig`], [`HistPostProcessConfig`], [`HistogramBinData`],
//!   [`LlState`], [`RangeData`], [`RangeResults`].
//! - [`bare_driver`] — [`BareDriver`]: p2p data, presets, timeouts, start/stop, one frame of bins.
//! - [`hist`] — the post-processing: 24 bins → up to four targets.
//! - [`history`] — [`FrameHistory`]: the wrap / event consistency checks against the frame before.
//! - [`histogram_driver`] — [`Vl53lxHistogramDriver`], the [`crate::vl53lx::driver::Vl53lxDriver`]
//!   the device layer runs.

pub mod bare_driver;
pub mod core;
pub mod hist;
pub mod histogram_driver;
pub mod history;
pub mod image;
pub mod math;
pub mod nvm;
pub mod regs;
pub mod tables;

pub use bare_driver::BareDriver;
pub use self::core::{
    BareDeviceState, HistConfig, HistPostProcessConfig, HistogramBinData, LlState, RangeData, RangeResults,
};
pub use histogram_driver::Vl53lxHistogramDriver;
pub use history::FrameHistory;
pub use image::{DeviceImage, RegBlock, RegBlockDef, RegField};
